#!/bin/bash
# Patch 0003: stop the keyboard target from polling 125 times a second.
#
# keyboard.rs only implements write_event(); key presses arrive as
# TargetCommand::WriteEvent and wake the target loop through rx.recv(), not
# through the tick. The generic 8 ms default therefore calls an empty poll()
# at 125 Hz for nothing. Mouse and ds5 keep their rates: their output is
# generated by the tick (velocity integration and controller reports).
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
SRC="$HOME/duo-build/inputplumber/src"
FILE="$SRC/src/input/target/mod.rs"
PATCH_OUT="$REPO/out/inputplumber-fork/0003-keyboard-idle-poll.patch"

[ -f "$FILE" ] || { echo "build tree missing: run build-inputplumber.sh first" >&2; exit 1; }

cp "$FILE" /tmp/target-mod.before

python3 - "$FILE" <<'PY'
import pathlib, sys

path = pathlib.Path(sys.argv[1])
text = path.read_text()

old = '''            "keyboard" => {
                let device = KeyboardDevice::new()?;
                let driver = TargetDriver::new(id, device, dbus);
                Ok(Self::Keyboard(driver))
            }'''
new = '''            "keyboard" => {
                let device = KeyboardDevice::new()?;
                // Key presses arrive as TargetCommand::WriteEvent and wake this
                // loop through the rx.recv() branch, so the periodic poll only
                // calls an empty poll(). The generic 8 ms default costs ~125
                // wakeups/s at idle and buys no latency.
                let options = TargetDriverOptions {
                    poll_rate: Duration::from_millis(500),
                    buffer_size: 2048,
                };
                let driver = TargetDriver::new_with_options(id, device, dbus, options);
                Ok(Self::Keyboard(driver))
            }'''

if old not in text:
    sys.exit("keyboard arm not found (already patched?)")
path.write_text(text.replace(old, new, 1))
print("patched keyboard arm")
PY

# Regenerate against the pristine upstream file so the patch is portable.
curl -fsSL https://raw.githubusercontent.com/ShadowBlip/InputPlumber/v0.82.0/src/input/target/mod.rs -o /tmp/target-mod.orig
diff -u /tmp/target-mod.orig "$FILE" > /tmp/0003.raw || true
sed -e '1s|.*|--- a/src/input/target/mod.rs|' \
    -e '2s|.*|+++ b/src/input/target/mod.rs|' \
    /tmp/0003.raw > "$PATCH_OUT"
echo "wrote $(wc -c < "$PATCH_OUT") bytes to $PATCH_OUT"

bash "$REPO/toolkit/cross/build-inputplumber.sh"
